import type { ReactNode } from "react";

/** Internal layout shared by domain panels. Shipped with its owning component. */
export function PanelHeader({
  icon,
  title,
  description,
  status,
  action,
  as: Heading = "h3",
}: {
  icon: ReactNode;
  title: string;
  description?: ReactNode;
  status?: ReactNode;
  action?: ReactNode;
  as?: "h2" | "h3";
}) {
  return (
    <div data-slot="panel-header" className="min-w-0">
      <div
        data-slot="panel-topline"
        className="grid min-w-0 grid-cols-[minmax(0,1fr)_auto] items-start gap-x-3 gap-y-2"
      >
        <div
          data-slot="panel-identity"
          className="flex min-w-0 items-start gap-3"
        >
          <span
            data-slot="panel-icon"
            aria-hidden="true"
            className="surface-control grid size-10 shrink-0 place-items-center rounded-full border bg-secondary text-secondary-foreground shadow-sm [&>svg]:size-4"
          >
            {icon}
          </span>
          <div
            data-slot="panel-heading"
            className="flex min-h-12 min-w-0 flex-col"
          >
            <Heading
              data-slot="panel-title"
              className="text-base font-medium leading-snug wrap-anywhere"
            >
              {title}
            </Heading>
            {description && (
              <p
                data-slot="panel-description"
                className="mt-1 text-sm leading-relaxed text-muted-foreground wrap-anywhere"
              >
                {description}
              </p>
            )}
          </div>
        </div>
        {(status != null || action != null) && (
          <div
            data-slot="panel-meta"
            className="ml-auto flex min-w-0 flex-wrap items-center justify-end gap-2 text-right text-sm text-muted-foreground"
          >
            {status != null && (
              <div data-slot="panel-status" className="min-w-0 wrap-anywhere">
                {status}
              </div>
            )}
            {action}
          </div>
        )}
      </div>
    </div>
  );
}

import type { ComponentProps } from "react";
import { PanelHeader } from "@/components/iot/internal/panel-header";

type PanelProps = ComponentProps<typeof PanelHeader> &
  Omit<ComponentProps<"section">, "title"> & {
    contentClassName?: string;
  };

/** Owns the surface, all four insets, header alignment and the content boundary. */
export function Panel({
  icon,
  title,
  description,
  status,
  action,
  as,
  className = "",
  contentClassName = "",
  children,
  ...props
}: PanelProps) {
  return (
    <section
      data-slot="panel"
      data-panel-layout=""
      className={`@container surface-raised grid min-w-0 gap-[var(--card-padding,24px)] rounded-xl border bg-card p-[var(--card-padding,24px)] text-card-foreground shadow-sm ${className}`}
      {...props}
    >
      <PanelHeader
        icon={icon}
        title={title}
        description={description}
        status={status}
        action={action}
        as={as}
      />
      <div
        data-slot="panel-content"
        className={`min-w-0 ${contentClassName || "space-y-5"}`}
      >
        {children}
      </div>
    </section>
  );
}

"use client";

import { Panel } from "@/components/iot/internal/panel";
import { useId, useRef, useState } from "react";
import { Power, LockKeyhole } from "lucide-react";
import { Switch } from "@/components/ui/switch";
import {
  CommandStatus,
  type CommandPhase,
} from "@/components/iot/command-status";

/** Resolve onCommand only on device acknowledgement; reported is owned by the caller. */
export function ActuatorSwitch({
  label,
  reported,
  online = true,
  locked = false,
  onCommand,
}: {
  label: string;
  reported: boolean | null;
  online?: boolean;
  locked?: boolean;
  onCommand: (enabled: boolean) => Promise<void>;
}) {
  const id = useId();
  const busy = useRef(false);
  const [requested, setRequested] = useState<boolean | null>(null);
  const [phase, setPhase] = useState<CommandPhase>("idle");
  const [error, setError] = useState("");
  const disabled =
    !online || locked || reported === null || phase === "pending";
  async function command(next: boolean) {
    if (disabled || busy.current) return;
    busy.current = true;
    setRequested(next);
    setPhase("pending");
    setError("");
    try {
      await onCommand(next);
      setPhase("confirmed");
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "发送失败，请重试。");
      setPhase("failed");
    } finally {
      busy.current = false;
    }
  }
  return (
    <Panel
      icon={<Power />}
      title={label}
      status={reported === null ? "状态未知" : reported ? "运行中" : "已关闭"}
    >
      <div className="flex items-center justify-between gap-4">
        <label htmlFor={id} className="text-sm">
          {label}开关
        </label>
        <Switch
          id={id}
          checked={reported === true}
          disabled={disabled}
          onCheckedChange={command}
        />
      </div>
      {(!online || locked) && (
        <p className="flex items-center gap-2 text-xs text-warning-text">
          <LockKeyhole aria-hidden="true" className="size-3.5" />
          {!online ? "设备离线，控制不可用" : "控制已锁定，仍可查看回读"}
        </p>
      )}
      <CommandStatus
        phase={phase}
        requested={requested === null ? "—" : requested ? "开启" : "关闭"}
        reported={reported === null ? "未知" : reported ? "开启" : "关闭"}
        message={error || undefined}
      />
    </Panel>
  );
}
